let rows=[],params={},bounds=[[-3,3],[-3,3]],view=bounds.map(b=>[...b]),result=null,worker=null,timer,serial=0,activeId=null,preset=null,filter='全部',request=0,saved=null,canSave=false,transform=null,points=[],drag=null,inspect=true;
