function renderBounds(){$('boundsInputs').innerHTML=bounds.map((b,i)=>`<div class="bound-row"><span>${'xy'[i]}</span><input type="number" step=".5" value="${b[0]}" data-axis="${i}" data-end="0" aria-label="${'xy'[i]} 最小值"><b>—</b><input type="number" step=".5" value="${b[1]}" data-axis="${i}" data-end="1" aria-label="${'xy'[i]} 最大值"></div>`).join('');for(const el of $('boundsInputs').querySelectorAll('input'))el.onchange=()=>{const next=bounds.map(b=>[...b]);next[+el.dataset.axis][+el.dataset.end]=+el.value;if(!el.value||next.some(b=>!b.every(Number.isFinite)||b[1]<=b[0]||b[1]-b[0]>10000)){toast('坐标上限应大于下限，跨度不超过 10000');renderBounds();return;}bounds=next;view=next.map(b=>[...b]);schedule(0);};}
function selected(){return(result?.regions||[]).filter(r=>$('regionSelect').value==='all'||String(r.index)===$('regionSelect').value);}
function regionBounds(){const regions=selected();return regions.length?[0,1].map(d=>[Math.min(...regions.map(r=>r.bounds[d][0])),Math.max(...regions.map(r=>r.bounds[d][1]))]):bounds;}
