function generate(){clearTimeout(timer);if(!computeClient)computeClient=createComputeClient('./plane-worker.mjs',{result:data=>{$('busy').hidden=true;document.querySelector('.analysis-workbench').removeAttribute('aria-busy');result=data;resultKey=requestedKey;apply();},error:message=>{$('busy').hidden=true;document.querySelector('.analysis-workbench').removeAttribute('aria-busy');$('renderState').textContent='生成失败';toast(message);}});requestedKey=geometryKey({rows,params,bounds,n:options.quality});if(!computeClient.submit({rows,params,bounds,n:options.quality})){if(pendingPresentation&&result)apply();$('renderState').textContent='图像已是最新 · 无需重算';return;}$('busy').hidden=false;$('renderState').textContent='后台计算中…';document.querySelector('.analysis-workbench').setAttribute('aria-busy','true');save();}
