function draw(){if(drawFrame!==null)return;drawFrame=requestAnimationFrame(()=>{drawFrame=null;drawNow();});}
function regionPath(reg){let path=regionPaths.get(reg);if(path)return path;path=new Path2D();const span=Math.max(...reg.bounds.map(b=>b[1]-b[0])),loops=reg.loops||[],closed=loops.length&&loops.every(p=>p.length>3&&Math.hypot(p[0][0]-p.at(-1)[0],p[0][1]-p.at(-1)[1])<span*1e-7);if(closed){for(const loop of loops){loop.forEach((p,i)=>i?path.lineTo(...p):path.moveTo(...p));path.closePath();}}else{const p=reg.positions;for(let i=0;i<p.length;i+=6){path.moveTo(p[i],p[i+1]);path.lineTo(p[i+2],p[i+3]);path.lineTo(p[i+4],p[i+5]);path.closePath();}}regionPaths.set(reg,path);return path;}
