  $('pointList').replaceChildren();for(const [i,p]of points.entries()){const b=document.createElement('button');b.className='point-chip';b.textContent=`P${i+1} (${p.p.map(number).join(', ')})`;b.onclick=()=>readPoint(p.p,p.ids);$('pointList').append(b);}
