function load(p,append=false){if(append&&rows.length+p.formulas.length>12){toast('最多同时显示 12 条曲线');return;}if(!append){rows=[];params={...p.params};bounds=p.bounds.map(b=>[...b]);view=bounds.map(b=>[...b]);preset=p;options.onlyBody=false;$('onlyBody').checked=false;}else{preset=null;for(const[k,v]of Object.entries(p.params))if(!(k in params))params[k]=v;}for(const[e,s]of p.formulas)rows.push(row(e,s));activeId=rows.at(-1)?.id;renderRows();parameters();renderBounds();schedule(0);}
