function insert(token){if(!rows.length){rows.push(row());activeId=rows[0].id;renderRows();}const input=(document.querySelector(`[data-id="${activeId}"]`)||$('surfaceList').firstElementChild).querySelector('textarea');if(insertMath(input,token))return;const funcs=['sqrt','sin','cos','tan','ln','exp','abs'];const s=input.selectionStart,e=input.selectionEnd,v=input.value.slice(s,e);let text=token,pos;if(funcs.includes(token)){text=token+'('+v+')';pos=v?text.length:token.length+1;}else if(token==='square'){text='^2';pos=2;}else if(token==='power'){text='^()';pos=2;}else if(token==='paren'){text='('+v+')';pos=v?text.length:1;}else if(token==='frac'){text='('+v+')/()';pos=v.length+4;}else pos=text.length;input.setRangeText(text,s,e,'end');input.focus();input.setSelectionRange(s+pos,s+pos);input.dispatchEvent(new Event('input',{bubbles:true}));}
